def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = opp[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Opponent's most recent runs
    def tail_run(seq):
        last = seq[-1]
        k = 0
        for a in reversed(seq):
            if a == last:
                k += 1
            else:
                break
        return k

    tail_d = tail_run(opp) if last_opp == 'D' else 0
    tail_c = tail_run(opp) if last_opp == 'C' else 0

    # Recent window stats
    w = min(12, n)
    rec_opp = opp[-w:]
    rec_c = rec_opp.count('C')
    rec_d = w - rec_c

    # My own defection used to exploit a naive cooperator; check if it worked
    my_last = my[-1]
    both_c = sum(1 for a, b in history if a == 'C' and b == 'C')

    # Hard hostility detection: sustained defection
    if n >= 6:
        if opp_d >= n - 2:
            return 'D'
        if rec_d >= w - 1 and rec_d >= 5:
            return 'D'

    # Long defection streak: punish firmly but don't lock forever
    if last_opp == 'D':
        if tail_d >= 3:
            # Defect while streak continues, but test cooperation once streak is very long
            if tail_d >= 6 and n < 90 and rng.random() < 0.12:
                return 'C'
            return 'D'
        # Isolated defection: retaliate once, then likely return to C
        if tail_d == 1:
            # If opponent mostly cooperates, forgive sometimes
            if opp_c >= n - 3 and n >= 4:
                if rng.random() < 0.4:
                    return 'C'
                return 'D'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    coop_rate = opp_c / n

    # Against near-perfect cooperator, cooperate mostly but exploit late/probe
    if opp_d <= 1 and n >= 4:
        # avoid predictable exploitation war; take some late DC value
        if n >= 96:
            return 'D'
        if n >= 80 and rng.random() < 0.5:
            return 'D'
        # rare probe to test if they retaliate
        if n >= 12 and n % 11 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Against strongly defective opponent who just cooperated: exploit rather than trust
    if coop_rate < 0.35:
        # they just cooperated after lots of D; likely noise/repair, but gain from DC
        if my_last == 'C' and both_c < n // 4:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'D'

    # Mixed opponents: forgiving tit-for-tat with measured exploitation
    if last_opp == 'C':
        # If we defected last and they still cooperated, they may be very forgiving: exploit a bit
        if my_last == 'D':
            if coop_rate > 0.6 and rng.random() < 0.55:
                return 'D'
            return 'C'

        # If opponent has been consistently cooperative recently, mostly cooperate
        if rec_c >= max(3, w - 2):
            # occasional probes only if they seem unresponsive to our defections
            if n >= 20 and n % 13 == 0 and rng.random() < 0.35:
                return 'D'
            return 'C'

        # Otherwise maintain cooperation
        return 'C'

    return 'C'
